/* @lc app=leetcode id=1906 lang=kotlin */ class Solution { fun minDifference(nums: IntArray, queries: Array<IntArray>): IntArray = Array(nums.size + 1) { IntArray(101) }.let { p -> IntArray(queries.size).also { ans -> (0 until nums.size).forEach { i -> (1..100).forEach { j -> p[i + 1][j] = p[i][j] }.also { p[i + 1][nums[i]]++ } }.also { (0 until queries.size).forEach { q -> intArrayOf(-1, 1000).let { v -> (1..100).forEach { j -> if (p[queries[q][1] + 1][j] - p[queries[q][0]][j] > 0) v.also { if (v[0] != -1 && j - v[0] < v[1]) v[1] = j - v[0] }.also { v[0] = j } }.also { ans[q] = if (v[1] == 1000) -1 else v[1] } } } } } } }